#include <iostream>
#include <cstring>
#include <queue>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

using i64 = long long;
using PII = pair<int, int>;

char grid1[15][15], grid2[15][15];
const int dx[4] = {-1, 1, 0, 0};
const int dy[4] = {0, 0, -1, 1};
int timeLayerIdx[65][15][15];
int minTime[15][15];
int nodeIdCounter = 1;

struct Edge {
    int from, to;
    i64 cap, flow;
    Edge() {}
    Edge(int f, int t, i64 c) : from(f), to(t), cap(c), flow(0) {}
};

struct DinicAlgorithm {
    int N;
    vector<Edge> edgeList;
    vector<vector<int>> adj;
    vector<int> depth, current;

    DinicAlgorithm(int n) : N(n), edgeList(), adj(n), depth(n), current(n) {}

    void connect(int u, int v, i64 capacity) {
        if (u == v) return;
        edgeList.emplace_back(u, v, capacity);
        adj[u].push_back(edgeList.size() - 1);
        edgeList.emplace_back(v, u, 0);
        adj[v].push_back(edgeList.size() - 1);
    }

    bool buildLevels(int src, int dst) {
        fill(depth.begin(), depth.end(), N + 1);
        queue<int> q;
        q.push(src);
        depth[src] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == dst) break;
            for (int idx : adj[u]) {
                Edge &e = edgeList[idx];
                if (e.flow < e.cap && depth[e.to] > depth[e.from] + 1) {
                    depth[e.to] = depth[e.from] + 1;
                    q.push(e.to);
                }
            }
        }
        return depth[dst] <= N;
    }

    i64 pushFlow(int u, int dst, i64 limit = -1) {
        if (u == dst || limit == 0) return limit;
        for (int &i = current[u]; i < (int)adj[u].size(); ++i) {
            Edge &e = edgeList[adj[u][i]];
            Edge &rev = edgeList[adj[u][i] ^ 1];
            if (depth[e.to] == depth[e.from] + 1) {
                i64 available = e.cap - e.flow;
                if (limit != -1 && available > limit) available = limit;
                i64 pushed = pushFlow(e.to, dst, available);
                if (pushed > 0) {
                    e.flow += pushed;
                    rev.flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    i64 maxFlow(int src, int dst) {
        i64 total = 0;
        while (buildLevels(src, dst)) {
            fill(current.begin(), current.end(), 0);
            i64 pushed;
            while ((pushed = pushFlow(src, dst)) > 0) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    memset(minTime, -1, sizeof(minTime));
    int n, t;
    cin >> n >> t;
    for (int i = 1; i <= n; ++i) {
        cin >> (grid1[i] + 1);
    }
    for (int layer = 0; layer <= t + 1; ++layer) {
        for (int r = 1; r <= n; ++r) {
            for (int c = 1; c <= n; ++c) {
                timeLayerIdx[layer][r][c] = nodeIdCounter++;
            }
        }
    }
    nodeIdCounter++;
    for (int i = 1; i <= n; ++i) {
        cin >> (grid2[i] + 1);
    }
    queue<PII> q;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') {
                q.push({i, j});
                minTime[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        auto [y, x] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int ny = y + dx[d], nx = x + dy[d];
            if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && grid1[ny][nx] != 'Y' && minTime[ny][nx] == -1) {
                minTime[ny][nx] = minTime[y][x] + 1;
                q.push({ny, nx});
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (minTime[i][j] == -1) minTime[i][j] = INT_MAX;
            if (minTime[i][j] > t) minTime[i][j] = INT_MAX;
        }
    }
    int source = 0, sink = nodeIdCounter - 1;
    DinicAlgorithm solver(nodeIdCounter);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] >= '1' && grid1[i][j] <= '9') {
                solver.connect(source, timeLayerIdx[0][i][j], grid1[i][j] - '0');
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
            for (int d = 0; d < 4; ++d) {
                int ny = i + dx[d], nj = j + dy[d];
                if (ny >= 1 && ny <= n && nj >= 1 && nj <= n && grid1[ny][nj] != 'Y' && grid1[ny][nj] != 'Z') {
                    for (int step = 0; step < t; ++step) {
                        if (minTime[ny][nj] >= step + 1 && minTime[i][j] > step) {
                            solver.connect(timeLayerIdx[step][i][j], timeLayerIdx[step + 1][ny][nj], 1000);
                        }
                    }
                }
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
            for (int step = 0; step <= t; ++step) {
                if (grid2[i][j] >= '1' && grid2[i][j] <= '9') {
                    solver.connect(timeLayerIdx[step][i][j], timeLayerIdx[t + 1][i][j], grid2[i][j] - '0');
                }
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
            if (grid2[i][j] >= '1' && grid2[i][j] <= '9') {
                solver.connect(timeLayerIdx[t + 1][i][j], sink, grid2[i][j] - '0');
            }
        }
    }
    cout << (int)solver.maxFlow(source, sink) << '\n';
    return 0;
}
